<div class="wrap">
  <div class="box">
    <div class="head">
      <span class="title">Lựa chọn lượt này</span>
      <span class="badge">choices</span>
    </div>
    <div class="body" id="list"></div>
  </div>
</div>
<pre id="raw" style="display:none;">$1</pre>
<script>
(function(){
  var raw=document.getElementById('raw');
  var list=document.getElementById('list');
  if(!raw||!list)return;
  var text=(raw.textContent||'').replace(/\r/g,'');
  var items=[];
  var re=/(?:^|\n)\s*(?:\d+|[一二三四五六七八九十]+)\s*[\.、\)．:：]\s*([\s\S]*?)(?=\n\s*(?:\d+|[一二三四五六七八九十]+)\s*[\.、\)．:：]\s*|$)/g;
  var m;
  while((m=re.exec(text))!==null){
    var body=(m[1]||'').replace(/\n+/g,' ').trim();
    if(body)items.push(body);
  }
  if(items.length===0){
    var lines=text.split('\n').map(function(l){return l.trim();}).filter(Boolean);
    lines.forEach(function(l){
      var c=l.replace(/^\s*(?:\d+|[一二三四五六七八九十]+)\s*[\.、\)．:：]?\s*/,'').trim();
      if(c)items.push(c);
    });
  }
  if(items.length===0){list.innerHTML='<div class="empty">Không có lựa chọn</div>';return;}
  items.forEach(function(item,i){
    var div=document.createElement('div');
    div.className='item';
    div.setAttribute('data-send',item);
    var num=document.createElement('span');
    num.className='num';
    num.textContent=String(i+1);
    var txt=document.createElement('span');
    txt.className='txt';
    txt.textContent=item;
    div.appendChild(num);
    div.appendChild(txt);
    div.addEventListener('click',function(){
      var t=this.getAttribute('data-send');
      if(!t)return;
      var ts=window.triggerSlash||(window.parent&&window.parent.triggerSlash);
      if(typeof ts==='function'){ts('/setinput '+t);}
      else{try{var inp=window.parent.document.querySelector('#send_textarea');if(inp){inp.value=t;inp.dispatchEvent(new Event('input',{bubbles:true}));}}catch(e){}}
    });
    list.appendChild(div);
  });
})();
</script>
</body>
</html>
